import React, { useCallback, useMemo } from 'react';
import { useIntl } from 'react-intl';

import {
  BasicContainer,
  ComparisonLine,
  DataStateHandler,
  SubFilter,
  Waterfall,
} from 'components';

import {
  PERFORMANCE_AND_BREAKDOWN_CONTRIBUTION_TITLE_I18N_ID,
  PERFORMANCE_AND_BREAKDOWN_WATERFALL_COLORS,
  PERFORMANCE_AND_BREAKDOWN_WATERFALL_DIMENSIONS_API_KEY,
  PERFORMANCE_AND_BREAKDOWN_WATERFALL_DIMENSIONS_STATE_KEY,
} from '../../constants';
import {
  usePerformanceAndBreakdownSectionData,
  usePerformanceAndBreakdownSectionUi,
} from '../../hooks';
import type {
  PerformanceAndBreakdownInnovationStageFilter,
  PerformanceAndBreakdownInnovationStageValue,
} from '../../types';
import {
  StyledBodyContainer,
  StyledComparisonLineContainer,
  StyledWaterfallChartContainer,
} from './ContributionSection.styles';

const CONTRIBUTION_WATERFALL_HEIGHT = '288px';

const SKELETON_PROPS = {
  height: '288px',
  width: '100%',
  length: 1,
  borderRadius: 'none' as const,
};

const INNOVATION_STAGE_VALUES =
  new Set<PerformanceAndBreakdownInnovationStageValue>([
    'y1',
    'y2',
    'y3',
    'y4',
    'y5',
  ]);

function isInnovationStageValue(
  value: string,
): value is PerformanceAndBreakdownInnovationStageValue {
  return INNOVATION_STAGE_VALUES.has(
    value as PerformanceAndBreakdownInnovationStageValue,
  );
}

interface ContributionSectionProps {
  kpi: string | undefined;
  innovationStageFilter: PerformanceAndBreakdownInnovationStageFilter | null;
  onInnovationStageSelect: (
    filter: PerformanceAndBreakdownInnovationStageFilter | null,
  ) => void;
  chartResetKey: number;
  dataTestId?: string;
}

export const ContributionSection: React.FC<ContributionSectionProps> = ({
  kpi,
  innovationStageFilter,
  onInnovationStageSelect,
  chartResetKey,
  dataTestId,
}) => {
  const { formatMessage } = useIntl();
  const { view, data } = usePerformanceAndBreakdownSectionData('contribution');
  const { measure, stateMessage } = usePerformanceAndBreakdownSectionUi(
    kpi,
    view,
  );

  const clickableIndexes = useMemo(
    () => data?.clickableIndexes ?? [],
    [data?.clickableIndexes],
  );

  const handleBarSelect = useCallback(
    (index: number | null) => {
      if (index === null || !data) {
        return;
      }

      if (innovationStageFilter?.barIndex === index) {
        onInnovationStageSelect(null);
        return;
      }

      const filterValue = data.filterValues?.[index];
      if (!filterValue || !isInnovationStageValue(filterValue)) {
        return;
      }

      onInnovationStageSelect({
        value: filterValue,
        label: data.labels[index] ?? filterValue.toUpperCase(),
        barIndex: index,
      });
    },
    [data, innovationStageFilter?.barIndex, onInnovationStageSelect],
  );

  const rightContent = useMemo(
    () => (
      <SubFilter.Select
        apiKey={PERFORMANCE_AND_BREAKDOWN_WATERFALL_DIMENSIONS_API_KEY}
        dataApiKey={PERFORMANCE_AND_BREAKDOWN_WATERFALL_DIMENSIONS_API_KEY}
        params={{}}
        stateKey={PERFORMANCE_AND_BREAKDOWN_WATERFALL_DIMENSIONS_STATE_KEY}
        valueLabel="View by:"
        shape="pill"
        size="medium"
        chips
        clearChips={false}
      />
    ),
    [],
  );

  return (
    <BasicContainer
      header={{
        title: formatMessage({
          id: PERFORMANCE_AND_BREAKDOWN_CONTRIBUTION_TITLE_I18N_ID,
        }),
        measure,
        titleSize: 'H4',
        rightContent,
      }}
      layout={{
        border: 'small',
        borderRadius: 'large',
        shadow: 'small',
        bodyPadding: false,
        bottomSeparator: 'border',
      }}
      fullWidth
      dataTestId={dataTestId}
    >
      <DataStateHandler
        loading={view === 'loading'}
        error={view === 'error'}
        empty={view === 'empty'}
        dataTestId={dataTestId ? `${dataTestId}-state` : undefined}
        message={stateMessage}
        skeletonProps={SKELETON_PROPS}
      >
        {view === 'ready' && data ? (
          <StyledBodyContainer>
            <StyledWaterfallChartContainer
              chartHeight={CONTRIBUTION_WATERFALL_HEIGHT}
            >
              <Waterfall
                key={chartResetKey}
                values={data.values}
                labels={data.labels}
                formattedData={data.formattedData}
                specialIndexes={data.specialIndexes}
                colors={PERFORMANCE_AND_BREAKDOWN_WATERFALL_COLORS}
                options={{ animation: false }}
                interactiveConfig={{
                  onBarSelect: handleBarSelect,
                  clickability: {
                    clickableIndexes,
                  },
                  fillHeight: true,
                  showTooltip: true,
                }}
              />
            </StyledWaterfallChartContainer>
            {data.comparisonLine?.data && (
              <StyledComparisonLineContainer>
                <ComparisonLine
                  data={data.comparisonLine.data}
                  gridColumnsLength={data.labels.length}
                  borderConfig={{ marginLeft: 16, marginRight: 16 }}
                  gridConfig={{ paddingLeft: 0, paddingRight: 0 }}
                />
              </StyledComparisonLineContainer>
            )}
          </StyledBodyContainer>
        ) : null}
      </DataStateHandler>
    </BasicContainer>
  );
};
